// Royal-only adapter. Shared NORIA ingress normalizes WhatsApp payload.
// No changes to existing tenants; this workflow does not expose a webhook.
const v = $json || {};
const env = n => { try { return String($env[n] || '').trim(); } catch { return ''; } };
const raw = v.raw_payload && typeof v.raw_payload === 'object' ? v.raw_payload : {};
const data = raw.data || raw;
const key = data.key || data.message?.key || {};
const expected = 'Royal 4x4';
// Deliberately fail closed when pending/unresolved: never process as the fallback JIW tenant.
if (String(v.instance || '').trim() !== expected) throw Error('ROYAL_WRONG_INSTANCE');
if (v.tenant_slug !== 'royal_4x4' || v.tenant_resolution?.source !== 'channels.config'
    || v.tenant_resolution?.channel?.config?.runtime !== 'royal_stock_v1'
    || v.tenant_resolution?.channel?.external_id !== expected) {
  return { json: { ok: true, royal: true, ignored: true, reason: 'royal_channel_not_active_or_identity_mismatch' } };
}
if (v.shouldProcess !== true || !['messages.upsert', 'messages.update', ''].includes(String(v.event || ''))) {
  return { json: { ok: true, royal: true, ignored: true, reason: 'unsupported_event' } };
}
const jidAlt = String(key.remoteJidAlt || data.remoteJidAlt || '').trim();
const jidOrig = String(v.remoteJid || '').trim();
const jid = /^\d{8,20}@s\.whatsapp\.net$/.test(jidAlt) ? jidAlt : jidOrig;
if (!/^\d{8,20}@(s\.whatsapp\.net|lid)$/.test(jid)) {
  return { json: {ok:true,royal:true,ignored:true,reason:'unsupported_chat'} };
}
// Do not accept the generic normalizer's synthetic message ID for deduplication.
const messageId = String(key.id || data.id || '').trim();
if (!messageId) return { json: {ok:true,royal:true,ignored:true,reason:'missing_real_message_id'} };
const message = data.message || {};
const sourceText = String(v.messageText || '').trim();
const text = v.contentType === 'audio' || Boolean(message.audioMessage)
  ? '[Áudio não suportado neste canal; por favor, envie uma mensagem de texto.]'
  : (sourceText && !/^\[(?:image|video|sticker|document|unknown)\]$/i.test(sourceText)
    ? sourceText : '[Mensagem não textual; envie uma descrição por texto.]');
if (text.length > 12000) return {json:{ok:true,royal:true,ignored:true,reason:'message_too_long'}};
const base = env('SUPABASE_URL').replace(/\/$/,'');
const apikey = env('SUPABASE_SERVICE_ROLE_KEY');
if (!base || !apikey) throw Error('ROYAL_SUPABASE_ENV_MISSING');
const result = await this.helpers.httpRequest({
  method:'POST',url:base+'/rest/v1/rpc/royal_stock_rpc',
  headers:{apikey,Authorization:'Bearer '+apikey,'Content-Type':'application/json'},
  json:true,timeout:15000,
  body:{p_op:'ingest',p_chat:jid,p_data:{instance:expected,message_id:messageId,text,
    name:String(v.contactName || data.pushName || 'Cliente').slice(0,160),
    from_me: v.is_manual_whatsapp_outbound === true || key.fromMe === true || data.fromMe === true}}
});
return {json:{ok:true,royal:true,queued:result?.queued===true,
  duplicate:result?.duplicate===true,ignored:result?.ignored===true}};

// NORIA — Royal 4x4 only, inventory-first worker v3.
// Catalog language is normalized locally; optional Royal system_prompt comes from claim.settings.
// Core, Nubia and Genesis remain unchanged.
// Queue and delivery remain owned by the existing royal_stock_rpc.
const TENANT='ac189d8a-b89a-4b56-af68-0a8b8ea8c46c';
const INSTANCE='Royal 4x4';
const CATALOG_URL='https://royal4x4.com.br/Veiculos';
const rlEnv=n=>{try{return String($env[n]||$vars?.[n]||'').trim();}catch(_){try{return String($env[n]||'').trim();}catch(_){return '';}}};
const nrm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const SUPA=rlEnv('SUPABASE_URL').replace(/\/$/,'');const KEY=rlEnv('SUPABASE_SERVICE_ROLE_KEY');
const EVO=rlEnv('EVOLUTION_API_URL_ROYAL_4X4').replace(/\/$/,'');const EVO_KEY=rlEnv('EVOLUTION_API_KEY_ROYAL_4X4');
const GEMINI_KEY=rlEnv('GEMINI_API_KEY_ROYAL_4X4')||rlEnv('GEMINI_API_KEY');
if(!SUPA||!KEY)throw Error('ROYAL_SUPABASE_ENV_MISSING');
const H={apikey:KEY,Authorization:'Bearer '+KEY,'Content-Type':'application/json'};
const req=async(method,url,body=null,head=H,timeout=30000)=>this.helpers.httpRequest({method,url,headers:head,json:true,timeout,...(body===null?{}:{body})});
const rpc=async(op,chat,data={})=>req('POST',SUPA+'/rest/v1/rpc/royal_stock_rpc',{p_op:op,p_chat:chat,p_data:data});
const search=async(filters={},page=1,size=10)=>req('POST',SUPA+'/rest/v1/rpc/royal_inventory_search_v1',{p_filters:filters,p_page:page,p_page_size:size});
// Gemini quota: same durable reservation RPC/controller as the CORE (magia_gemini_reserve).
// A dedicated Royal key may belong to another quota project, so it only reads *_ROYAL_4X4 limits.
const geminiRate=(()=>{const sfx=rlEnv('GEMINI_API_KEY_ROYAL_4X4')?'_ROYAL_4X4':'';const scope=rlEnv('GEMINI_RATE_SCOPE'+sfx);
 const lim=name=>Number(rlEnv(name+sfx)||0);const rpm=lim('GEMINI_MAX_RPM'),tpm=lim('GEMINI_MAX_TPM'),rpd=lim('GEMINI_MAX_RPD');
 return {scope,rpm,tpm,rpd,required:rlEnv('GEMINI_RATE_CONTROL_REQUIRED').toLowerCase()==='true',
  distributed:/^[a-zA-Z0-9._:-]{1,120}$/.test(scope)&&[rpm,tpm,rpd].every(v=>Number.isFinite(v)&&v>0)};})();
async function reserveGemini(settings,model,payload){
 if(geminiRate.required&&!geminiRate.distributed)throw Error('GEMINI_QUOTA:controller_not_configured');
 const configured=Number(settings.gemini_daily_limit??500);const dailyLimit=Number.isFinite(configured)?Math.trunc(configured):500;
 const leaseId='royal:'+Date.now()+':'+Math.random().toString(36).slice(2,10);
 const ttl=Math.max(20000,Math.min(Number(rlEnv('GEMINI_LEASE_TTL_MS')||30000),120000));
 const estimated=Math.max(1,Math.ceil(JSON.stringify(payload).length/3.5)+Math.max(1,Number(payload?.generationConfig?.maxOutputTokens||250)));
 let res;
 try{res=await req('POST',SUPA+'/rest/v1/rpc/magia_gemini_reserve',{p_tenant_id:TENANT,p_daily_limit:dailyLimit,p_model:model,p_lease_id:leaseId,p_estimated_tokens:estimated,
  ...(geminiRate.distributed?{p_scope:geminiRate.scope,p_max_concurrent:Math.max(1,Math.min(Number(rlEnv('GEMINI_MAX_CONCURRENT_CALLS')||2),20)),
   p_max_rpm:geminiRate.rpm,p_max_tpm:geminiRate.tpm,p_max_rpd:geminiRate.rpd,p_lease_ttl_ms:ttl,
   p_probe_cooldown_ms:Math.max(1000,Math.min(Number(rlEnv('GEMINI_CIRCUIT_COOLDOWN_MS')||30000),300000))}:{})},H,5000);}
 catch(_){throw Error('GEMINI_QUOTA:controller_unavailable');}
 if(!res||res.allowed!==true)throw Error('GEMINI_QUOTA:'+String(res?.reason||'unavailable').slice(0,40));
 return geminiRate.distributed?{scope:geminiRate.scope,model,lease_id:leaseId}:null;
}
async function releaseGemini(lease,outcome){
 if(!lease)return;
 try{await req('POST',SUPA+'/rest/v1/rpc/magia_gemini_release',{p_scope:lease.scope,p_model:lease.model,p_lease_id:lease.lease_id,p_outcome:outcome,p_cooldown_ms:30000},H,5000);}catch(_){}
}
const brl=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const fmt=(v,index)=>`${index}. ${v.name}${v.version?' — '+v.version:''}\n${v.year_manufacture}/${v.year_model} | ${v.mileage_km==null?'KM não informado':Number(v.mileage_km).toLocaleString('pt-BR')+' km'} | ${brl(v.price)}${v.armored?' | BLINDADO':''}\n${v.url}`;
function initialFilter(){return {query:'',category:null,max_price:null,min_price:null,min_year:null,max_km:null,blindado:null};}
function extractPrice(text){
 // Captura: "até 100 mil", "até uns 100 mil", "menos de R$ 100.000".
 const t=nrm(text);
 const m=t.match(/\b(?:ate|menos de|abaixo de|no maximo|limite de|por ate)\s*(?:(?:uns?|cerca de|aproximadamente|mais ou menos|por volta de)\s*)?(?:r\$\s*)?(\d{1,3}(?:[.,]\d{3})*|\d{4,8})\s*(mil|k)?\b/);
 if(!m)return null;
 let n=Number(m[1].replace(/[.,](?=\d{3}(?:\D|$))/g,''));if(m[2])n*=1000;
 return Number.isFinite(n)&&n>=1000&&n<=10000000?n:null;
}
function categoryFrom(t){
 const s=nrm(t);
 if(/\b(motos?|motocicletas?|ducati)\b/.test(s))return 'moto';
 if(/\b(picapes?|caminhonetes?|caminhonetas?|pickup|pickups)\b/.test(s))return 'picape';
 if(/\b(suvs?|utilitarios esportivos)\b/.test(s))return 'suv';
 if(/\b(sedans?|sedas?)\b/.test(s))return 'sedan';
 if(/\b(hatches?|hatchback)\b/.test(s))return 'hatch';
 return null;
}
function normalizedSearchQuery(value){
 let s=nrm(value).replace(/\s+/g,' ');
 // Retira expressões de faixa de preço antes da remoção das palavras de conversa.
 // Preserva números de modelos: Peugeot 208, Porsche 911, BMW 320i.
 s=s.replace(/\b(?:ate|menos de|abaixo de|no maximo|limite de|por ate)\s*(?:(?:uns?|cerca de|aproximadamente|mais ou menos|por volta de)\s*)?(?:r\$\s*)?(?:\d{1,3}(?:[.,]\d{3})*|\d{4,8})\s*(?:mil|k)?\b/g,' ');
 s=s.replace(/\b(?:ano|fabricado em|a partir de|depois de|antes de)\s*(?:19|20)\d{2}\b/g,' ');
 s=s.replace(/\b(?:quais|qual|quantos|quantas|tipos|modelos|opcoes|opcao|veiculos|veiculo|automoveis|automovel|carros|carro|disponiveis|disponivel|estoque|catalogo|lista|listar|listar|todos|todas|todo|toda|tem|teria|teriam|possuem|possui|me|mostre|mostra|mostrar|manda|mandar|envia|enviar|pode|podem|poderia|gostaria|queria|quero|conhecer|saber|ver|olhar|procurando|procuro|procurar|busco|buscando|preciso|algum|alguma|uns|umas|uma|um|oi|ola|bom|dia|boa|tarde|noite|aqui|ai|nessa|nesses|nesse|na|no|nos|nas|pra|para|por|favor|voces|voce|vcs|o|a|os|as|e|ou|de|da|do|das|dos|em|com|que|seja|se|so|somente|apenas|ate|menos|abaixo|no|maximo|limite|reais|r\$|mil|blindado|blindada|automatico|automatica)\b/g,' ');
 s=s.replace(/\b(?:suvs?|picapes?|caminhonetes?|caminhonetas?|pickups?|sedans?|sedas?|hatches?|hatchback|motos?|motocicletas?)\b/g,' ');
 // Termos transacionais nunca são marca/modelo no catálogo da Royal.
 s=s.replace(/\b(?:vender|vendendo|venda|vendas|vende|vendem|vendido|vendidos|vendida|vendidas|comprar|comprando|compra|compras|compram|anuncio|anuncios|anunciado|anunciados|anunciada|anunciadas|oferta|ofertas|oferece|oferecem|temos|disponibiliza|disponibilizam|a venda|para venda|pra venda|pra|pro|seus|suas|seu|sua|nosso|nossa|nossos|nossas|usados|seminovos|zero km)\b/g,' ');
 s=s.replace(/\bjeeps\b/g,'jeep');
 return s.replace(/[^a-z0-9\s-]/g,' ').replace(/\s+/g,' ').trim().slice(0,90).trim();
}
function fallbackAction(text,state){
 const t=nrm(text).replace(/\s+/g,' ');
 if(/^(oi+|ola+|opa|bom dia|boa tarde|boa noite|tudo bem|alo|oi tudo bem)[\s!.?]*$/.test(t))return {action:'hello'};
 // Pedido para vender veículo próprio NÃO equivale a procurar anúncios para comprar.
 if(/\b(?:quero|gostaria|preciso|pretendo|estou|vou)\s+(?:de\s+)?(?:vender|anunciar)\b/.test(t)||/\b(?:vender|anunciar)\s+(?:o\s+|a\s+)?(?:meu|minha)\b/.test(t)||/\btenho\s+(?:um|uma)\b.{0,55}\b(?:para|pra)\s+(?:vender|anunciar)\b/.test(t))return {action:'human'};
 if(/\b(vendedor|atendente|humano|pessoa real|negociar|negociacao|financiamento|test drive|agendar visita|avaliar meu carro)\b/.test(t))return {action:'human'};
 if(/^(mais|mais opcoes|proximos|proximo|continuar|mostre mais|quero mais|outras opcoes|pagina seguinte|proxima pagina)[!.?\s]*$/.test(t))return {action:'next'};
 const digit=t.match(/(?:opcao|numero|n[.ºo]?|gostei d[ao]|quero [oa]|o carro|o veiculo)\s*[#:-]?\s*(\d{1,2})\b/);
 const ordinal=t.match(/\b(primeir[oa]|segund[oa]|terceir[oa]|quart[oa]|quint[oa])\b/);
 const ix=digit?Number(digit[1]):ordinal?({'primeiro':1,'primeira':1,'segundo':2,'segunda':2,'terceiro':3,'terceira':3,'quarto':4,'quarta':4,'quinto':5,'quinta':5}[ordinal[1]]):null;
 if(ix&&ix<=10)return {action:'details',index:ix};
 if(state.selected_vehicle_id && /\b(esse|essa|ele|ela|tem |possui |caracteristicas|detalhes|cambio|combustivel|revisad|blindad|camer|interior|motor|ipva|garantia|sobre o carro)\b/.test(t))return {action:'details_question',question:text};
 const category=categoryFrom(t);
 const maxPrice=extractPrice(t);
 let q=normalizedSearchQuery(t);
 // Comparativos vagos não são itens catalogados. Solicita interpretação da IA ou mais dados.
 const vague=/\b(economico|economicos|economica|economicas|barato|baratos|barata|baratas|custo beneficio|confortavel|confortaveis|espacoso|espacosos|recomenda|recomendacao|ideal para familia|mais bonito)\b/.test(t);
 if(q||category||maxPrice||/\b(catalogo|estoque|carros?|veiculos?|automoveis?|todos|todas|quais|opcoes|ofertas|anuncios|a venda|vender|vendem|lista|listar|mostra|mostrar|ver)\b/.test(t))
  return {action:'search',query:q,category,max_price:maxPrice,blindado:/\bblindad[oa]\b/.test(t)||null,deterministic:!vague};
 return {action:'clarify'};
}
async function classify(text,state,settings){
 const local=fallbackAction(text,state);
 if(['hello','human','next','details','details_question'].includes(local.action)|| (local.action==='search'&&local.deterministic===true))return {...local,used_fallback:false};
 if(!GEMINI_KEY)return {...local,used_fallback:true,ai_error:'GEMINI_KEY_MISSING'};
 const model=String(settings.ai_model||'gemini-3.5-flash-lite').replace(/^models\//,'');
 if(!/^gemini-[\w.-]+$/.test(model))return {...local,used_fallback:true,ai_error:'MODEL_INVALID'};
 const baseInstruction='Você classifica pedidos de clientes da Royal 4x4, sem citar nem inventar veículos. Responda SOMENTE JSON com action (hello,search,next,details,details_question,human,clarify), query (somente marca/modelo citado, sem palavras de conversa), category (picape,suv,sedan,hatch,moto ou null), max_price,min_price,min_year,max_km (número ou null), blindado (true ou null), index (1 a 10 ou null), question (texto sobre veículo selecionado ou vazio). Catálogo/todos: search com query vazia. Mais opções: next. Dúvidas sobre veículo já selecionado: details_question. Atendimento humano/financiamento/visita/negociação: human. Não deduza categoria a partir de modelo ambíguo.';
 const customInstructions=typeof settings.system_prompt==='string'?settings.system_prompt.slice(0,6500).trim():'';
 const instruction=baseInstruction+(customInstructions?'\n\nDIRETRIZES EXCLUSIVAS DA ROYAL:\n'+customInstructions:'');
 let lease=null;
 try{
  const body={system_instruction:{parts:[{text:instruction}]},contents:[{role:'user',parts:[{text:JSON.stringify({message:text,has_selected_vehicle:!!state.selected_vehicle_id,previous_filter:state.filter||{}})}]}],generationConfig:{temperature:0,maxOutputTokens:250,responseMimeType:'application/json'}};
  lease=await reserveGemini(settings,model,body);
  const r=await req('POST','https://generativelanguage.googleapis.com/v1beta/models/'+encodeURIComponent(model)+':generateContent',body,{'x-goog-api-key':GEMINI_KEY,'Content-Type':'application/json'},20000);
  await releaseGemini(lease,'success');lease=null;
  if(!r?.candidates?.[0]?.content?.parts?.length)throw Error('GEMINI_EMPTY');
  const raw=r.candidates[0].content.parts.map(p=>p.text||'').join('');const o=JSON.parse(raw.replace(/```(?:json)?|```/g,''));
  if(!['hello','search','next','details','details_question','human','clarify'].includes(o.action))throw Error('GEMINI_INVALID_ACTION');
  return {...o,used_fallback:false};
 }catch(e){const m=String(e?.message||e);const is429=/\b429\b/.test(m);
  await releaseGemini(lease,is429?'rate_limit':/\b5\d\d\b/.test(m)?'upstream_server':/timeout|ETIMEDOUT|ECONN|ESOCKET/i.test(m)?'network_or_timeout':'released');
  return {...local,used_fallback:true,ai_error:is429?'GEMINI_RATE_LIMIT':m.slice(0,75)};}
}
function safeFilters(a,old={}){
 const num=(v,low,high)=>v==null||v===''?null:(Number.isFinite(Number(v))&&Number(v)>=low&&Number(v)<=high?Number(v):null);
 return {query:normalizedSearchQuery(String(a.query||'')),
  category:['picape','suv','sedan','hatch','moto'].includes(a.category)?a.category:null,
  max_price:num(a.max_price,1000,100000000),min_price:num(a.min_price,1000,100000000),min_year:num(a.min_year,1950,2100),
  max_km:num(a.max_km,0,20000000),blindado:a.blindado===true?true:null};
}
async function getVehicle(id){
 if(!/^\d{4,12}$/.test(String(id)))return null;
 const r=await req('GET',SUPA+'/rest/v1/royal_inventory_vehicles?select=vehicle_id,name,version,year_manufacture,year_model,mileage_km,price,armored,category,url,last_seen_at&tenant_id=eq.'+TENANT+'&vehicle_id=eq.'+id+'&available=eq.true&limit=1');
 return Array.isArray(r)?r[0]||null:null;
}
function clearHtmlTags(html){return String(html||'').replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,' ').replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,' ').replace(/<(?:br|\/div|\/li|\/p|\/h\d|\/section)\b[^>]*>/gi,'\n').replace(/<[^>]*>/g,' ').replace(/&nbsp;|&#160;/gi,' ').replace(/&amp;/gi,'&').replace(/&quot;/gi,'"').split(/[\r\n]+/).map(s=>s.replace(/\s+/g,' ').trim()).filter(Boolean);}
async function siteDetails(v){
 if(!/^https:\/\/(?:www\.)?royal4x4\.com\.br\/Veiculo\/[a-zA-Z0-9/_?=%&.+-]+$/.test(v.url)||!v.url.includes('/'+v.vehicle_id+'/detalhes'))throw Error('ROYAL_DETAIL_LINK_INVALID');
 const response=await this.helpers.httpRequest({method:'GET',url:v.url,headers:{'User-Agent':'Mozilla/5.0','Accept':'text/html'},json:false,timeout:25000});
 const raw=typeof response==='string'?response:String(response?.body||response?.data||'');
 if(raw.length<1800)throw Error('ROYAL_DETAIL_PAGE_EMPTY');
 const lines=clearHtmlTags(raw);
 const titleIdx=lines.findIndex(x=>nrm(x)===nrm(v.name));
 if(titleIdx<0)throw Error('ROYAL_DETAIL_TITLE_MISMATCH');
 const stopIdx=lines.findIndex((x,i)=>i>titleIdx&&/(envie sua proposta|valor do ve[ií]culo|simular financiamento|ligue agora)/i.test(x));
 const scope=lines.slice(titleIdx,stopIdx>titleIdx?stopIdx:Math.min(lines.length,titleIdx+140));
 const field=label=>{let i=scope.findIndex(x=>nrm(x)===nrm(label));return i>=0?scope[i+1]||'':'';};
 const ch=scope.findIndex(x=>nrm(x)==='caracteristicas');const end=scope.findIndex((x,i)=>i>ch&&nrm(x).startsWith('informacoes do veiculo'));
 const features=ch>=0?scope.slice(ch+1,end>ch?end:Math.min(ch+25,scope.length)).filter(x=>x.length<=100).slice(0,25):[];
 const infoAt=scope.findIndex(x=>nrm(x).startsWith('informacoes do veiculo'));
 const description=infoAt>=0?scope.slice(infoAt+1,infoAt+9).join(' ').slice(0,1100):'';
 return {year:field('Ano'),transmission:field('Câmbio'),fuel:field('Combustível'),km:field('Km'),features,description,checked_at:new Date().toISOString()};
}
function detailAnswer(v,details,question){
 const basic=`${v.name}${v.version?' — '+v.version:''}\n${v.year_manufacture}/${v.year_model} | ${v.mileage_km==null?'KM não informado':Number(v.mileage_km).toLocaleString('pt-BR')+' km'} | ${brl(v.price)}\n${v.url}`;
 const facts=[details.transmission?'Câmbio: '+details.transmission:'',details.fuel?'Combustível: '+details.fuel:'',details.features.length?'Características anunciadas: '+details.features.slice(0,12).join(', '):''].filter(Boolean);
 if(!question)return `Encontrei os detalhes na página desse anúncio:\n\n${basic}${facts.length?'\n\n'+facts.join('\n'):''}\n\nQuer saber alguma característica específica ou falar com um vendedor?`;
 const q=nrm(question);const look= q.includes('camer')?'camera':q.includes('blindad')?'blindad':q.includes('chave')?'chave':q.includes('revis')?'revis':q.includes('manual')?'manual':q.includes('licencia')?'licencia':q.includes('cambio')?'cambio':q.includes('combust')?'combust':null;
 if(look==='cambio'&&details.transmission)return `${v.name}: o anúncio informa câmbio ${details.transmission}.\n${v.url}`;
 if(look==='combust'&&details.fuel)return `${v.name}: o anúncio informa combustível ${details.fuel}.\n${v.url}`;
 if(look){const f=details.features.find(x=>nrm(x).includes(look));if(f)return `${v.name}: o anúncio lista “${f}”.\n${v.url}`;}
 return `Consultei a página específica do ${v.name}, mas não consegui confirmar essa característica pelo anúncio. Posso encaminhar sua dúvida a um vendedor.\n${v.url}`;
}
async function makeReply(text,state,settings){
 const a=await classify(text,state,settings);const aiState={...state,last_ai_error:a.ai_error||null};
 if(a.action==='hello')return {reply:'Olá! Bem-vindo à Royal 4x4. 😊 Você procura alguma marca ou modelo, tem uma faixa de preço em mente ou quer conhecer nosso catálogo?',stage:'Qualificacao',handoff:false,state:aiState};
